use std::{path::Path, time::Instant};
use gwt::cli::execution_state::{self as execution, ExecutionControlStatus, ExecutionOwnerKey};

fn observe(path: &Path, completed: bool, session_id: &str, owner_number: u64, guarded: bool) -> (u128, usize) {
    let started = Instant::now();
    let mut reads = 0;
    for _ in 0..12 {
        let matches = (!guarded || completed) && {
            reads += 1;
            execution::load(path).unwrap().is_some_and(|record| {
                execution::integrity_ok(&record)
                    && record.primary_session_id == session_id
                    && record.owner_number == owner_number
                    && record.status == ExecutionControlStatus::Completed
            })
        };
        assert!(!matches);
        std::hint::black_box(matches);
    }
    (started.elapsed().as_nanos(), reads)
}

fn main() {
    let arg = std::env::args().nth(1).unwrap();
    let path = Path::new(&arg);
    let record = execution::load(path).unwrap().unwrap();
    assert!(execution::integrity_ok(&record));
    let completed = record.status == ExecutionControlStatus::Completed;
    assert!(!completed, "requires a non-Completed authority input");
    let owner = ExecutionOwnerKey { kind: record.owner_kind, number: record.owner_number };
    let ledger = execution::load_generation_ledger(path, owner).unwrap().unwrap();
    println!("{{\"kind\":\"input\",\"record_hash\":\"{}\",\"ledger_hash\":\"{}\",\"generations\":{},\"checks_per_sample\":12,\"paired_rounds\":20}}", record.content_hash, ledger.content_hash, ledger.generations.len());
    let sample = |guarded| observe(path, completed, &record.primary_session_id, record.owner_number, guarded);
    sample(false);
    sample(true);
    for round in 0..20 {
        let (old, new) = if round % 2 == 0 {
            (sample(false), sample(true))
        } else {
            let new = sample(true);
            (sample(false), new)
        };
        println!("{{\"kind\":\"pair\",\"round\":{round},\"old_ns\":{},\"old_reads\":{},\"new_ns\":{},\"new_reads\":{}}}",old.0,old.1,new.0,new.1);
    }
    let after = execution::load(path).unwrap().unwrap();
    let after_ledger = execution::load_generation_ledger(path, owner).unwrap().unwrap();
    assert_eq!(record.content_hash, after.content_hash, "input changed");
    assert_eq!(ledger.content_hash, after_ledger.content_hash, "ledger changed");
    println!("{{\"kind\":\"validated\",\"input_unchanged\":true}}");
}
